const auth=()=>typeof portalAuth!=='undefined'?portalAuth:null;
async function jwt(){const a=auth();if(!a)return null;const r=await a.getSession();if(r.error)throw Error('نشست قابل بررسی نیست؛ دوباره وارد شوید.');return r.data.session?.access_token||null;}
function reset(){generation++;identity=null;messages=[];visible=6;lastRequest=null;feed.replaceChildren();tools.replaceChildren();busy=false;input.value='';state.textContent='حساب تغییر کرد؛ هزارآوا را دوباره باز کنید.';send.disabled=false;}
const roles={visitor:'بازدیدکننده',student:'هنرجو',teacher:'استاد',secretary:'منشی',admin:'مدیر'};
async function request(body){const current=generation;const token=await jwt();const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const r=await fetch(endpoint,{method:'POST',headers:{apikey:key,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(body),signal:controller.signal});const data=await r.json();if(current!==generation)throw Error('حساب تغییر کرده است');if(!r.ok){if(r.status===401)reset();throw Error(data.message||'دریافت پاسخ انجام نشد');}return data;}catch(e){if(e.name==='AbortError')throw Error('پاسخ سرور طول کشید؛ دوباره تلاش کنید.');throw e;}finally{clearTimeout(timer);}}
function context(){return typeof page!=='undefined'?page:'home';}
function render(){const stick=feed.scrollHeight-feed.scrollTop-feed.clientHeight<100;feed.replaceChildren();if(messages.length>visible)feed.append(btn('پیام‌های قبلی ('+(messages.length-visible).toLocaleString('fa-IR')+')',()=>{visible+=8;render();},'ha-earlier'));for(const m of messages.slice(-visible)){const a=el('article','ha-message '+(m.user?'ha-user':'ha-answer'));if(m.text)a.append(el('p','',m.text));if(m.node)a.append(m.node);for(const c of m.cards||[])a.append(card(c));if(m.sources?.length){const details=el('details','ha-sources');details.append(el('summary','','رکوردهای مبنای گزارش ('+m.sources.length.toLocaleString('fa-IR')+')'));for(const s of m.sources)details.append(btn(s.label,()=>showRecord(s)));a.append(details);}for(const action of m.actions||[])a.append(actionButton(action));feed.append(a);}if(stick||!feed.scrollTop)feed.scrollTop=feed.scrollHeight;}
