function card(c){const a=el('article','ha-card');a.append(el('strong','',c.title),el('p','',c.body));if(c.table&&c.id)a.append(btn('بازکردن رکورد اصلی ←',()=>showRecord(c),'ha-card-link'));else if(c.href)a.append(safeAnchor(c.href,'شناخت این ساز ←'));else if(c.page)a.append(btn('بازکردن بخش مربوط ←',()=>navigate(c.page,c.id),'ha-card-link'));return a;}
const safeAnchor=(href,label)=>{const allowed=/^\/(?:register\.html|portal\.html|index\.html|instruments\/[a-z-]+\.html)(?:#[\w-]*)?$/.test(href);if(!allowed)return el('span','','لینک در دسترس نیست');const a=el('a','ha-card-link',label);a.href=href;return a;};
function navigate(target,id){if(target==='journey'&&window.PracticeJournal){panel.close();window.PracticeJournal.open(id);return;}if(target==='register'){panel.close();if(typeof registration==='function')registration();else location.href='/portal.html#register';return;}const map={receipts:'payments',register:'login'};target=map[target]||target;if(typeof go==='function'&&typeof views!=='undefined'&&views[target]){panel.close();go(target);if(id)setTimeout(()=>{const s=document.querySelector('[data-student-id="'+CSS.escape(id)+'"]');s?.scrollIntoView({block:'center',behavior:'smooth'});s?.classList.add('ha-highlight');},100);}else{const sections={teachers:'masters',rules:'rules',schedule:'week',students:'masters',portal:'home'};location.href=target==='login'?'/portal.html':'/index.html#'+(sections[target]||'courses');}}
function actionButton(a){if(a.type==='link')return safeAnchor(a.href,a.label);return btn(a.label,()=>{if(a.type==='journey'){panel.close();if(window.PracticeJournal)window.PracticeJournal.open(a.studentId);else location.href='/portal.html#journey';}else if(a.type==='compose')draft(a.kind);else if(a.type==='review')draft('review_request',a.id);else if(a.type==='search')search();else if(a.type==='guide'){const b=document.querySelector('.discover-trigger');if(b){panel.close();b.click();}else location.href='/index.html#discover';}},'ha-action');}
async function showRecord(c){try{const r=await request({action:'record',table:c.table,id:c.id});add(r);}catch(e){error(e,()=>showRecord(c));}}
function error(e,retry){state.textContent='ارتباط کامل نشد';const box=el('div','ha-error');box.append(el('p','',e.message||'دریافت انجام نشد'));if(retry)box.append(btn('تلاش دوباره',retry));add({node:box});}
async function open(){if(!panel.open)panel.showModal();state.textContent='در حال بررسی نشست و دسترسی…';try{const r=await request({action:'bootstrap'});if(identity&&(identity.actor!==r.actor||identity.role!==r.role))reset();identity=r;tools.replaceChildren();const shortcuts=r.role==='teacher'?[['ارزیابی و تمرین هنرجو','journey'],['برنامه کلاس‌ها','schedule']]:r.role==='student'?[['کلاس‌های من','portal'],['پیگیری رسید','monthly'],['تغییر برنامه','schedule_changes'],['تمرین من','journey']]:r.role==='admin'?[['جست‌وجوی هنرجو','students'],['درخواست‌های تغییر برنامه','schedule_changes'],['پیام‌های هنرجویان','feedback']]:r.role==='secretary'?[['جست‌وجوی هنرجو','students'],['تقویم کلاس‌ها','schedule']]:[];for(const [label,target] of shortcuts)tools.append(btn(label,()=>navigate(target),'ha-prompt')); for(const text of r.prompts||[])tools.append(btn(text,()=>text.includes('جست‌وجو')?search():ask(text),'ha-prompt'));if(r.role==='admin')tools.append(btn('انتخاب بازهٔ مالی',rangeForm,'ha-prompt'));if(r.teacherId&&r.role==='admin')tools.append(btn('یادداشت کلاس‌های من',()=>ask('یادداشت کلاس‌ها',{intent:'notes'}),'ha-prompt'));state.textContent=(roles[r.role]||'کاربر')+' · '+(r.modelConfigured?'تشخیص پرسش با سرویس مدل؛ داده و عملیات محدود به سیستم':'ابزارهای واقعی فعال · مدل زبانی متصل نیست');if(!messages.length)add({text:'سلام. من هزارآوا هستم؛ دستیار آوای هزاردستان. '+(r.role==='visitor'?'برای شناخت سازها و روند ثبت‌نام کمک می‌کنم.':'دربارهٔ کلاس‌ها و کارهای مجاز حسابتان بپرسید. ثبت هر پیام یا درخواست به تأیید شما نیاز دارد.')});}catch(e){error(e,open);}}
async function ask(text,extra={}){if(busy)return;if(!identity){await open();if(!identity)return;}busy=true;send.disabled=true;lastRequest={text,extra};add({user:true,text});state.textContent='در حال خواندن اطلاعات مجاز…';const g=generation;try{const r=await request({action:'ask',text,page:context(),...extra});if(g!==generation)return;add(r);state.textContent=r.modelUnavailable?'سرویس مدل در دسترس نیست؛ پاسخ از ابزار قطعی سیستم است':r.modelConnected?'پرسش با مدل تشخیص داده شد · پاسخ از دادهٔ سیستم':(roles[r.role]||'کاربر')+' · پاسخ از ابزارهای دادهٔ واقعی';}catch(e){if(g===generation)error(e,()=>ask(text,extra));}finally{if(g===generation){busy=false;send.disabled=false;input.focus({preventScroll:true});}}}
composer.onsubmit=e=>{e.preventDefault();const text=input.value.trim();if(!text||busy)return;input.value='';ask(text);};input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();composer.requestSubmit();}});
function form(title){const f=el('form','ha-draft');f.append(el('h3','',title));return f;}
