function draft(kind,id){if(kind==='request'&&identity?.role==='student'){add({text:'برای تغییر روز، ساعت یا استاد، برنامه پیشنهادی را در فرم تغییر کلاس انتخاب کنید؛ پس از بررسی مدیر اعمال می‌شود.',node:btn('درخواست تغییر برنامه کلاس',()=>{panel.close();if(typeof go==='function')go('schedule_changes');else location.href='/portal#schedule_changes';},'ha-primary')});}if(!identity||identity.role==='visitor'){add({text:'برای ثبت پیام ابتدا وارد پرتال شوید.'});return;}const names={feedback:'پیام شما، فرصتی برای بهترشدن آموزشگاه',request:'درخواست برای بررسی مدیریت',teacher_note:'یادداشت جلسه و تمرین اختصاصی',notice:'پیام برای پرتال هنرجو',review_request:'نتیجهٔ بررسی درخواست'};const f=form(names[kind]);let choices=identity.classes||[];if(kind==='teacher_note')choices=choices.filter(s=>s.teacherId===identity.teacherId);if(['request','teacher_note','notice'].includes(kind)){if(!choices.length){add({text:'کلاس مجازی برای این عملیات در دسترس نیست.'});return;}field(f,'کلاس مربوط','student_id','text',choices.map(c=>[c.id,c.label]));}if(kind==='feedback'){field(f,'نوع پیام','kind','text',[['suggestion','پیشنهاد'],['criticism','انتقاد'],['appreciation','قدردانی']]);const subject=field(f,'موضوع','subject');subject.minLength=3;subject.maxLength=120;}if(kind==='request')field(f,'نوع درخواست','kind','text',identity.role==='student'?[['makeup','جلسه جبرانی'],['absence','غیبت']]:[['time_change','تغییر زمان'],['makeup','جلسه جبرانی'],['absence','غیبت']]);if(kind==='review_request')field(f,'نتیجه بررسی','status','text',[['reviewed','بررسی شد'],['rejected','رد درخواست']]);const message=field(f,kind==='review_request'?'توضیح نتیجه':'متن پیام / یادداشت',kind==='review_request'?'review_note':'message','textarea');message.minLength=kind==='feedback'?10:3;if(kind==='teacher_note'){field(f,'تمرین پیشنهادی','practice','textarea').required=false;}f.append(el('small','','پیش از ثبت، متن و مقصد را بررسی و تأیید خواهید کرد.'));const submit=el('button','ha-primary','دیدن پیش‌نمایش');submit.type='submit';f.append(submit);const holder=el('div');holder.append(f);add({node:holder});let requestKey=null,previousPayload=null;
f.onsubmit=async e=>{e.preventDefault();if(!f.reportValidity()||submit.disabled)return;const data=Object.fromEntries(new FormData(f));if(id)data.id=id;const serial=JSON.stringify(data);if(serial!==previousPayload){requestKey=crypto.randomUUID();previousPayload=serial;}submit.disabled=true;try{const r=await request({action:'prepare',kind,requestKey,data});if(r.completed){showSuccess(r.result);return;}const preview=el('section','ha-preview');preview.append(el('h3','','پیش‌نمایش · هنوز ثبت نشده'));for(const [k,v] of Object.entries(r.preview||{})){const labels={title:'عملیات',subject:'موضوع',class:'کلاس',message:'متن',practice:'تمرین',notice:'توضیح',status:'نتیجه',review_note:'توضیح بررسی'};preview.append(el('p','',(labels[k]||k)+': '+v));}const expiry=el('small','','اعتبار پیش‌نمایش: ۱۰ دقیقه');const confirm=btn('تأیید می‌کنم؛ ثبت نهایی',async()=>{if(confirm.disabled)return;confirm.disabled=true;try{const result=await request({action:'confirm',operationId:r.id,confirmed:true});if(result.completed){holder.replaceChildren(el('p','ha-success','با موفقیت ثبت شد.'));showSuccess(result);}else throw Error('ثبت تأیید نشده است');}catch(e){error(e);confirm.disabled=false;}} ,'ha-primary');preview.append(expiry,confirm,btn('ویرایش پیش‌نویس',()=>{holder.replaceChildren(f);requestKey=null;previousPayload=null;}));holder.replaceChildren(preview);}catch(e){const note=el('p','ha-error',e.message+'؛ پیش‌نویس حفظ شده است.');f.append(note);}finally{submit.disabled=false;}};}
function showSuccess(r){const cards=[{title:'رسید عملیات',body:'شناسه ثبت: '+r.record_id+'\nشناسه پیگیری: '+r.operation_id}];if(['request','teacher_note','review_request'].includes(r.kind))Object.assign(cards[0],{table:'hezarava_records',id:r.record_id});else if(r.kind==='feedback')Object.assign(cards[0],{table:'student_feedback',id:r.record_id});add({text:'عملیات با موفقیت در سیستم ثبت شد.'+(r.kind==='request'?' تصمیم نهایی و تغییر برنامه با مدیریت است.':''),cards});}
function search(){const f=form('جست‌وجوی سریع هنرجو'),q=field(f,'نام، نام خانوادگی، رشته یا استاد','query');q.maxLength=80;const b=el('button','ha-primary','جست‌وجو');b.type='submit';f.append(b);f.onsubmit=e=>{e.preventDefault();ask('جست‌وجوی '+q.value,{intent:'students',query:q.value});};add({node:f});q.focus();}
